mapper.select:
SELECT s.seat_id, s.seat_code, s.seat_name, s.seat_type, s.position_x, s.position_y, s.floor_number, s.area, s.ip_address, s.mac_address, s.seat_status, s.enabled_flag, s.remark, s.deleted_flag, s.create_user_id, s.create_user_name, s.create_time, s.update_time FROM t_oa_seat s WHERE s.deleted_flag = 0
AND s.seat_code LIKE CONCAT('%', #{query.seatCode}, '%')
AND s.seat_name LIKE CONCAT('%', #{query.seatName}, '%')
AND s.seat_type = #{query.seatType}
AND s.seat_status = #{query.seatStatus}
AND s.area = #{query.area}
AND s.floor_number = #{query.floorNumber}
ORDER BY s.seat_code ASC, s.create_time DESC

mapper.update:
UPDATE t_oa_seat
SET seat_status = #{status}, update_time = NOW()
WHERE seat_id = #{seatId}
